import { unlink } from 'fs/promises';
import { isAbsolute, join, relative, resolve } from 'path';

const committed = new WeakSet<Express.Multer.File>();
export function commitUpload(file?: Express.Multer.File) {
  if (file) committed.add(file);
}
export function uploadCommitted(file: Express.Multer.File) {
  return committed.has(file);
}

// Only remove filenames generated by our upload storage, never a client-supplied path.
export async function removeUpload(url: string | null | undefined) {
  if (
    !url ||
    !/^\/uploads\/(images|audio)\/[\w-]+\.(jpg|jpeg|png|webp|gif|mp3)$/i.test(
      url,
    )
  )
    return;
  try {
    await unlink(join(process.cwd(), url.slice(1)));
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code !== 'ENOENT')
      console.warn('Could not remove obsolete upload');
  }
}

export async function cleanupUpload(filePath: string) {
  const root = resolve(process.cwd(), 'uploads');
  const path = relative(root, resolve(filePath));
  if (!path || path.startsWith('..') || isAbsolute(path)) return;
  try {
    await unlink(resolve(root, path));
  } catch {
    /* Preserve the original request error. */
  }
}
